public virtual void SetLength(int sz)
{
    if (sz < 0)
        throw new ArgumentOutOfRangeException(nameof(sz), "Length must be non‑negative.");

    if (sz > _capacity)
    {
        // Expand the underlying storage.
        int newCapacity = Math.Max(sz, _capacity * 2);
        var newBuffer = new byte[newCapacity];
        Array.Copy(_buffer, newBuffer, _length);
        _buffer = newBuffer;
        _capacity = newCapacity;
    }

    _length = sz;

    // Adjust the current position if it is now beyond the new length.
    if (_position > _length)
        _position = _length;
}

