public void remove(int key) {
    Node prev = null;
    Node curr = head;
    while (curr != null && curr.key != key) {
        prev = curr;
        curr = curr.next;
    }
    if (curr == null) {
        return; // key not found
    }
    if (prev == null) {
        head = curr.next; // removing the head node
    } else {
        prev.next = curr.next; // bypass the removed node
    }
    size--;
}

