public virtual void RemoveState(ATNState state)
{
    if (state == null)
        return;

    int idx = states.IndexOf(state);
    if (idx < 0)
        return;

    // Remove the state from the ATN's state list
    states.RemoveAt(idx);
    // Invalidate the removed state's number
    state.stateNumber = ATNState.INVALID_STATE_NUMBER;

    // Re‑number the remaining states so that their state numbers stay contiguous
    for (int i = idx; i < states.Count; i++)
    {
        states[i].stateNumber = i;
    }
}

