public IntervalSet(List<Interval> intervals) {
    // Initialize the internal list
    this.intervals = new ArrayList<>();

    // Copy the provided intervals if any
    if (intervals != null) {
        this.intervals.addAll(intervals);
    }

    // Sort intervals by their start value
    Collections.sort(this.intervals, Comparator.comparingInt(Interval::getStart));

    // Merge overlapping or adjacent intervals
    List<Interval> merged = new ArrayList<>();
    for (Interval cur : this.intervals) {
        if (merged.isEmpty() ||
            merged.get(merged.size() - 1).getEnd() < cur.getStart()) {
            // No overlap, add the interval as‑is
            merged.add(cur);
        } else {
            // Overlap – extend the previous interval's end
            Interval last = merged.get(merged.size() - 1);
            last.setEnd(Math.max(last.getEnd(), cur.getEnd()));
        }
    }

    // Replace the original list with the merged one
    this.intervals = merged;
}

