public void CopyUpdatedCells(IWorkbook workbook) {
    // Assume there is a field `Map<String, Object> updatedCells` where the key is in the form "SheetName!A1"
    for (Map.Entry<String, Object> entry : updatedCells.entrySet()) {
        String cellKey = entry.getKey();          // e.g., "Sheet1!B2"
        Object value = entry.getValue();

        // Split the key into sheet name and cell address
        String[] parts = cellKey.split("!");
        if (parts.length != 2) {
            continue; // skip malformed entries
        }
        String sheetName = parts[0];
        CellReference cellRef = new CellReference(parts[1]);

        // Get or create the target sheet
        ISheet sheet = workbook.getSheet(sheetName);
        if (sheet == null) {
            sheet = workbook.createSheet(sheetName);
        }

        // Get or create the target row
        IRow row = sheet.getRow(cellRef.getRow());
        if (row == null) {
            row = sheet.createRow(cellRef.getRow());
        }

        // Get or create the target cell
        ICell cell = row.getCell(cellRef.getCol());
        if (cell == null) {
            cell = row.createCell(cellRef.getCol());
        }

        // Write the value to the cell, handling common data types
        if (value instanceof String) {
            cell.setCellValue((String) value);
        } else if (value instanceof Number) {
            cell.setCellValue(((Number) value).doubleValue());
        } else if (value instanceof Boolean) {
            cell.setCellValue((Boolean) value);
        } else if (value instanceof Date) {
            cell.setCellValue((Date) value);
        } else if (value != null) {
            cell.setCellValue(value.toString());
        }
    }
}

