public void copyUpdatedCells(Workbook workbook) {
    // Assume `updatedCells` is a Map where the key is a cell reference like "Sheet1!A1"
    // and the value is the new string value that should be written to that cell.
    for (Map.Entry<String, String> entry : updatedCells.entrySet()) {
        String ref = entry.getKey();                 // e.g., "Sheet1!A1"
        String[] parts = ref.split("!");             // parts[0] = sheet name, parts[1] = cell address
        if (parts.length != 2) {
            continue; // skip malformed references
        }

        Sheet sheet = workbook.getSheet(parts[0]);
        if (sheet == null) {
            // If the sheet does not exist, create it.
            sheet = workbook.createSheet(parts[0]);
        }

        // Convert the cell address (e.g., "A1") to row and column indices.
        CellReference cellRef = new CellReference(parts[1]);
        int rowIndex = cellRef.getRow();
        int colIndex = cellRef.getCol();

        // Obtain or create the target row.
        Row row = sheet.getRow(rowIndex);
        if (row == null) {
            row = sheet.createRow(rowIndex);
        }

        // Obtain or create the target cell.
        Cell cell = row.getCell(colIndex);
        if (cell == null) {
            cell = row.createCell(colIndex);
        }

        // Write the new value into the cell.
        cell.setCellValue(entry.getValue());
    }
}

