public void SerializeTokens(ILittleEndianOutput out1) {
    // Write the number of tokens first
    out1.WriteVInt(tokens.Count);
    // Then write each token's data
    foreach (var token in tokens) {
        out1.WriteVInt(token.Position);
        out1.WriteVInt(token.StartOffset);
        out1.WriteVInt(token.EndOffset);
        // Write payload if present
        if (token.Payload != null) {
            out1.WriteVInt(token.Payload.Length);
            out1.WriteBytes(token.Payload, 0, token.Payload.Length);
        } else {
            out1.WriteVInt(0);
        }
    }
}

