public static final int tagger(byte[] b, int ptr) {
    final int sz = b.length;
    if (ptr == 0) return match(b, ptr, tagger);
    while (ptr < sz) {
        if (b[ptr] == '\n') return -1;
        final int m = match(b, ptr, tagger);
        if (m >= 0) return m;
        ptr = nextLF(b, ptr);
    }
    return -1;
}

