public static Ptg createPtg(LittleEndianInput in) {
    byte id = in.readByte();
    if (id < 0x20) {
        return createBasePtg(id, in);
    }
    Ptg retval = createClassifiedPtg(id, in);
    if (id >= 0x60) {
        retval.setClass(CLASS_ARRAY);
    } else if (id >= 0x40) {
        retval.setClass(CLASS_VALUE);
    } else {
        retval.setClass(CLASS_REF);
    }
    return retval;
}

public void FreeBefore(int pos){
    int toFree = count - (nextPos - pos);
    Debug.Assert(toFree >= 0);
    Debug.Assert(toFree <= count);
    int index = nextWrite - count;
    if (index < 0){
        index += positions.Length;
    }
    for (int i = 0; i < toFree; i++){
        if (index == positions.Length){
            index = 0;
        }
        positions[index].Reset();
        index++;
    }
    count -= toFree;
}

