public Collection<RevCommit> call() throws GitAPIException, InvalidRefNameException {
    checkCallable();
    try {
        if (repo.exactRef(Constants.R_STASH) == null)
            return Collections.emptyList();
    } catch (IOException e) {
        throw new InvalidRefNameException(
                MessageFormat.format(JGitText.get().cannotRead, Constants.R_STASH), e);
    }
    final ReflogCommand refLog = new ReflogCommand(repo);
    refLog.setRef(Constants.R_STASH);
    final Collection<ReflogEntry> stashEntries = refLog.call();
    if (stashEntries.isEmpty())
        return Collections.emptyList();
    final List<RevCommit> stashCommits = new ArrayList<>(stashEntries.size());
    try (RevWalk walk = new RevWalk(repo)) {
        for (ReflogEntry entry : stashEntries) {
            try {
                RevCommit commit = walk.parseCommit(entry.getNewId());
                stashCommits.add(commit);
            } catch (IOException e) {
                throw new JGitInternalException(
                        MessageFormat.format(JGitText.get().cannotReadCommit, entry.getNewId()), e);
            }
        }
    }
    return stashCommits;
}

