public final String validate(String uri, int start, int end, String name)throws URISyntaxException {
    for (int i = start; i < end; ) {
        char ch = uri.charAt(i);
        if ((ch >= 'a' && ch <= 'z')|| (ch >= 'A' && ch <= 'Z')|| (ch >= '0' && ch <= '9')|| isRetained(ch)) {
            i++;
        } else if (ch == '%') {
            if (i + 2 >= end) {
                throw new URISyntaxException(uri, "Incomplete % sequence in " + name, i);
            }
            int d1 = hexToInt(uri.charAt(i + 1));
            int d2 = hexToInt(uri.charAt(i + 2));
            if (d1 == -1 || d2 == -1) {
                throw new URISyntaxException(uri, "Invalid % sequence: " + uri.substring(i, i + 3) + " in " + name, i);
            }
            i += 3;
        } else {
            throw new URISyntaxException(uri, "Illegal character in " + name, i);
        }
    }
    return uri.substring(start, end);
}

public LongsRef next(int count) throws IOException {
    assert nextValues.length >= 0;
    assert count > 0;
    assert nextValues.offset + nextValues.length <= nextValues.longs.length;
    if (position >= valueCount) {
        throw new EOFException();
    }
    final int remaining = valueCount - position - 1;
    if (remaining <= 0) {
        throw new EOFException();
    }
    count = Math.min(remaining, count);
    if (nextValues.offset == nextValues.longs.length) {
        final long remainingBlocks = format.byteCount(packedIntsVersion, remaining, bitsPerValue);
        final int blocksToRead = (int) Math.min(remainingBlocks, nextBlocks.length);
        in.readBytes(nextBlocks, 0, blocksToRead);
        if (blocksToRead < nextBlocks.length) {
            Arrays.fill(nextBlocks, blocksToRead, nextBlocks.length, (byte) 0);
        }
        bulkOperation.decode(nextBlocks, 0, nextValues.longs, 0, iterations);
        nextValues.offset = 0;
    }
    nextValues.length = Math.min(nextValues.longs.length - nextValues.offset, count);
    position += nextValues.length;
    return nextValues;
}

public override Int64sRef Next(int count){
    Debug.Assert(nextValues.Length >= 0);
    Debug.Assert(count > 0);
    Debug.Assert(nextValues.Offset + nextValues.Length <= nextValues.Int64s.Length);
    nextValues.Offset += nextValues.Length;
    int remaining = m_valueCount - position - 1;
    if (remaining <= 0){
        throw new System.IO.EndOfStreamException();
    }
    count = Math.Min(remaining, count);
    if (nextValues.Offset == nextValues.Int64s.Length){
        long remainingBlocks = format.ByteCount(packedIntsVersion, remaining, m_bitsPerValue);
        int blocksToRead = (int)Math.Min(remainingBlocks, nextBlocks.Length);
        m_in.ReadBytes(nextBlocks, 0, blocksToRead);
        if (blocksToRead < nextBlocks.Length){
            Array.Clear(nextBlocks, blocksToRead, nextBlocks.Length - blocksToRead);
        }
        bulkOperation.Decode(nextBlocks, 0, nextValues.Int64s, 0, iterations);
        nextValues.Offset = 0;
    }
    nextValues.Length = Math.Min(nextValues.Int64s.Length - nextValues.Offset, count);
    position += nextValues.Length;
    return nextValues;
}

public override int Next(int n){
    currentSentence += n;
    if (n < 0){
        if (text.Index == text.EndIndex){
            ++currentSentence;
        }
        if (currentSentence < 0){
            currentSentence = 0;
            text.SetIndex(text.BeginIndex);
            return Done;
        }else{
            text.SetIndex(sentenceStarts[currentSentence]);
        }
    }else if (n > 0){
        if (currentSentence >= sentenceStarts.Length){
            currentSentence = sentenceStarts.Length - 1;
            text.SetIndex(text.EndIndex);
            return Done;
        }else{
            text.SetIndex(sentenceStarts[currentSentence]);
        }
    }
    return Current;
}

public long skip(long byteCount) throws IOException {
    if (byteCount < 0) {
        throw new IllegalArgumentException("byteCount < 0: " + byteCount);
    }
    synchronized (lock) {
        if (end == pos && fillBuf() == -1) {
            return 0;
        }
        if (byteCount < 1) {
            return 0;
        }
        if (end - pos >= byteCount) {
            pos += byteCount;
            return byteCount;
        }
        long read = end - pos;
        pos = end;
        while (read < byteCount) {
            if (fillBuf() == -1) {
                return read;
            }
            if (end - pos >= byteCount - read) {
                pos += byteCount - read;
                return byteCount;
            }
            read += (end - pos);
            pos = end;
        }
        return byteCount;
    }
}

