public void remove(int key) {
    if (root == null) return;
    root = removeRecursive(root, key);
}

private Node removeRecursive(Node current, int key) {
    if (current == null) return current;
    if (key < current.key) {
        current.left = removeRecursive(current.left, key);
    } else if (key > current.key) {
        current.right = removeRecursive(current.right, key);
    } else {
        if (current.left == null && current.right == null) {
            return null;
        } else if (current.left == null) {
            return current.right;
        } else if (current.right == null) {
            return current.left;
        } else {
            int smallestInRightSubtree = findSmallest(current.right);
            current.key = smallestInRightSubtree;
            current.right = removeRecursive(current.right, smallestInRightSubtree);
        }
    }
    return current;
}

private int findSmallest(Node node) {
    return node.left == null ? node.key : findSmallest(node.left);
}

class Node {
    int key;
    Node left;
    Node right;

    public Node(int key) {
        this.key = key;
        left = null;
        right = null;
    }
}
