public void readFully(byte[] dst, int offset, int byteCount) throws IOException {
    int bytesRead = 0;
    while (bytesRead < byteCount) {
        int bytesJustRead = read(dst, offset + bytesRead, byteCount - bytesRead);
        if (bytesJustRead == -1) {
            throw new EOFException("reached end of stream after reading " + bytesRead + " bytes, expected to read " + byteCount);
        }
        bytesRead += bytesJustRead;
    }
}
