public static String toHex(long value) {
    StringBuilder sb = new StringBuilder(16);
    for (int i = 15; i >= 0; i--) {
        int nibble = (int) ((value >>> (i * 4)) & 0xF);
        if (nibble < 10) {
            sb.append((char) ('0' + nibble));
        } else {
            sb.append((char) ('a' + (nibble - 10)));
        }
    }
    return sb.toString();
}
