            case '"':
                result.append("&quot;");
                break;
            case '&':
                result.append("&amp;");
                break;
            case '<':
                result.append("&lt;");
                break;
            case '>':
                result.append("&gt;");
                break;
            case '\'':
                result.append("&#x27;");
                break;
            case '/':
                result.append("&#x2F;");
                break;
            default:
