public void removeState(ATNState state) {
    if (state == null) {
        return;
    }

    // Remove all incoming transitions
    for (ATNState from : state.getIncoming()) {
        from.removeTransitionTo(state);
    }

    // Remove all outgoing transitions
    for (Transition trans : state.getTransitions()) {
        ATNState target = trans.getTarget();
        target.removeIncoming(state);
    }

    // Remove from the state list
    states.remove(state);
}

