    if (dst == null) {
        throw new NullPointerException("dst == null");
    }
    if (offset < 0 || byteCount < 0 || offset + byteCount > dst.length) {
        throw new IndexOutOfBoundsException();
    }
    while (byteCount > 0) {
        int bytesRead = read(dst, offset, byteCount);
        if (bytesRead == -1) {
            throw new EOFException();
        }
        offset += bytesRead;
        byteCount -= bytesRead;
    }
}
