public virtual string GetText(Interval interval)
{
    int start = interval.a;
    int stop = interval.b;
    if (start < 0 || stop < 0)
    {
        return string.Empty;
    }
    LazyInit();
    if (stop >= tokens.Count)
    {
        stop = tokens.Count - 1;
    }
    StringBuilder buf = new StringBuilder();
    for (int i = start; i <= stop; i++)
    {
        IToken t = tokens[i];
        if (t.Type == TokenConstants.EOF)
        {
            break;
        }
        buf.Append(t.Text);
    }
    return buf.ToString();
}

